"use client";

import { useSyncExternalStore } from "react";

const unsubscribe = () => {
  // Mount state never changes after hydration, so there is nothing to tear down.
};
const subscribe = () => unsubscribe;
export const useMounted = () =>
  useSyncExternalStore(
    subscribe,
    () => true,
    () => false
  );

"use client";

import { useTheme } from "next-themes";

import type { ReactFC } from "@/lib/types";
import { useMounted } from "@/registry/hooks/useMounted";
import { ThemeSwitchSlider } from "@/registry/new-york/theme-switch-slider/ThemeSwitchSlider";

export interface ThemeSwitchNextThemesProps {
  className?: string | undefined;
}

export const ThemeSwitchNextThemes: ReactFC<ThemeSwitchNextThemesProps> = ({
  className,
}) => {
  const { theme, resolvedTheme, setTheme } = useTheme();
  const isDark = resolvedTheme === "dark";
  const toggleTheme = () => setTheme(isDark ? "light" : "dark");
  const mounted = useMounted();

  if (!mounted) {
    return null;
  }

  return (
    <ThemeSwitchSlider
      theme={theme || "light"}
      setTheme={setTheme}
      isDark={isDark}
      toggleTheme={toggleTheme}
      className={className}
    />
  );
};

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
